(494892, 48138, 4793, '<td valign="top">Very nice comp, colors -10</td>', 'Very nice comp, colors -10', '2003-11-26 00:42:48.000000', NULL, 1),
(494895, 48202, 11078, '<td valign="top">Are you asking? A nice surprise for some nice lady I hope she says yes.<br/>A nice Idea but a bit on the darkside</td>', 'Are you asking? A nice surprise for some nice lady I hope she says yes.A nice Idea but a bit on the darkside', '2003-11-26 00:43:55.000000', NULL, 1),
(494901, 48086, 11078, '<td valign="top">I dont really see this as a surprise more like kinky. with the nice undies<br/>Its a nice sharp and colourful photograph but I dont really see surprise <br/>Maybe you should have put the undies on yourself and given us more of a surprise ha ha  only joking!</td>', 'I dont really see this as a surprise more like kinky. with the nice undiesIts a nice sharp and colourful photograph but I dont really see surprise Maybe you should have put the undies on yourself and given us more of a surprise ha ha  only joking!', '2003-11-26 00:47:05.000000', NULL, 1),
