(494912, 47437, 11078, '<td valign="top">Looks like a fun time or maybe too much plonk! nice happy shot</td>', 'Looks like a fun time or maybe too much plonk! nice happy shot', '2003-11-26 00:53:27.000000', NULL, 1),
(494918, 48284, 11078, '<td valign="top">This happened to me and it wasent a joke!  13 years on and she is a joy to my life.<br/>I expect this was staged if it isnt good luck and hope you have agreat life with him/her or maybe both! Its a nice clear image well done!</td>', 'This happened to me and it wasent a joke!  13 years on and she is a joy to my life.I expect this was staged if it isnt good luck and hope you have agreat life with him/her or maybe both! Its a nice clear image well done!', '2003-11-26 00:55:44.000000', NULL, 1),
(494920, 48250, 11078, '<td valign="top">I dont want to look I hope he landed away from the little girl Nice image very clear and bright.</td>', 'I dont want to look I hope he landed away from the little girl Nice image very clear and bright.', '2003-11-26 00:57:24.000000', NULL, 1),
(494922, 48312, 11078, '<td valign="top">Great photo nice clear image and looksa  really happymoment!</td>', 'Great photo nice clear image and looksa  really happymoment!', '2003-11-26 00:59:28.000000', NULL, 1),
(494923, 48207, 11078, '<td valign="top">Nice photo but I dont see surprise</td>', 'Nice photo but I dont see surprise', '2003-11-26 01:00:36.000000', NULL, 1),
(494924, 48323, 11078, '<td valign="top">Yum is that caramel popcorn My favorite</td>', 'Yum is that caramel popcorn My favorite', '2003-11-26 01:01:39.000000', NULL, 1),
(494927, 48324, 11078, '<td valign="top">How did you upload such a big picture  I love this one and I think I feel she is going to like her surprise, you have such warm and inviting looking hands! I also love the sparkle on her earing and beautiful smile when I first looked through the thumb pics I liked this the best and I still do</td>', 'How did you upload such a big picture  I love this one and I think I feel she is going to like her surprise, you have such warm and inviting looking hands! I also love the sparkle on her earing and beautiful smile when I first looked through the thumb pics I liked this the best and I still do', '2003-11-26 01:06:26.000000', NULL, 1),
(494928, 48234, 11078, '<td valign="top">I love hedgehogs its a shame we cant see his cute little face.</td>', 'I love hedgehogs its a shame we cant see his cute little face.', '2003-11-26 01:07:23.000000', NULL, 1),
(494929, 48247, 11078, '<td valign="top">Who''s scaring who</td>', 'Who''s scaring who', '2003-11-26 01:08:34.000000', NULL, 1),
