INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(494945, 48005, 11078, '<td valign="top">A nice surprise for a lucky lady<br/>Image looks a bit on the bright side<br/>Great Idea</td>', 'A nice surprise for a lucky ladyImage looks a bit on the bright sideGreat Idea', '2003-11-26 01:19:32.000000', NULL, 1),
(494946, 48318, 11078, '<td valign="top">Nice photo, great expression and clarity</td>', 'Nice photo, great expression and clarity', '2003-11-26 01:20:57.000000', NULL, 1),
(494947, 48138, 11078, '<td valign="top">M amd Ms everytime! nice idea</td>', 'M amd Ms everytime! nice idea', '2003-11-26 01:21:57.000000', NULL, 1),
(494948, 48177, 11078, '<td valign="top">Nice capture of a cute animal I like this</td>', 'Nice capture of a cute animal I like this', '2003-11-26 01:23:01.000000', NULL, 1),
(494951, 48301, 11078, '<td valign="top">What a scary sight good surprise look though</td>', 'What a scary sight good surprise look though', '2003-11-26 01:24:09.000000', NULL, 1),
(494952, 48307, 8953, '<td valign="top">Fun idea:) I know i have been surprised like this a few times. this image would have more impact (I think) If the flash had not been quite so harsh. still a nice take on the challenge.</td>', 'Fun idea:) I know i have been surprised like this a few times. this image would have more impact (I think) If the flash had not been quite so harsh. still a nice take on the challenge.', '2003-11-26 01:25:02.000000', NULL, 1),
(494953, 48126, 11078, '<td valign="top">This looks like two photos joined together. its a bit washed out good idea though</td>', 'This looks like two photos joined together. its a bit washed out good idea though', '2003-11-26 01:25:33.000000', NULL, 1),
(494955, 48141, 11078, '<td valign="top">Clever idea</td>', 'Clever idea', '2003-11-26 01:26:17.000000', NULL, 1),
(494956, 48163, 11078, '<td valign="top">What a lovely image The butterfly doesnt look real but the eyes of the child are amazing</td>', 'What a lovely image The butterfly doesnt look real but the eyes of the child are amazing', '2003-11-26 01:28:22.000000', NULL, 1),
(494957, 48295, 11078, '<td valign="top">Funny and I hope it isnt true!</td>', 'Funny and I hope it isnt true!', '2003-11-26 01:29:06.000000', NULL, 1),
(494958, 48278, 8953, '<td valign="top">oops! looks like it might hurt:( action like this is hard to do. what would have made this more effective would have been less camera shake. having both the climber and the background moving is a bit distracting. but no question, he looks surprised .</td>', 'oops! looks like it might hurt:( action like this is hard to do. what would have made this more effective would have been less camera shake. having both the climber and the background moving is a bit distracting. but no question, he looks surprised .', '2003-11-26 01:29:11.000000', NULL, 1),
(494960, 48308, 11078, '<td valign="top">shame about the red eye and it is a bit blurred but cute childand she does look guilty</td>', 'shame about the red eye and it is a bit blurred but cute childand she does look guilty', '2003-11-26 01:30:44.000000', NULL, 1),
(494962, 48144, 8953, '<td valign="top">wonderful model and look of surprise. this image would have had a bit more impact if you could have dropped the background out all together. Stiil a fun shot</td>', 'wonderful model and look of surprise. this image would have had a bit more impact if you could have dropped the background out all together. Stiil a fun shot', '2003-11-26 01:31:35.000000', NULL, 1),
(495062, 48046, 7151, '<td valign="top">Cute.  Though, I''m not totally certain what the surprise is - first time by himself, or did he miss...?  The tone works well for this shot, and lighting is good.  I think a little more of the toilet would have given it a better atmosphere, a little more sense of the moment.  6</td>', 'Cute.  Though, I''m not totally certain what the surprise is - first time by himself, or did he miss...?  The tone works well for this shot, and lighting is good.  I think a little more of the toilet would have given it a better atmosphere, a little more sense of the moment.  6', '2003-11-26 02:50:23.000000', NULL, 1),
(495063, 47975, 7151, '<td valign="top">Highest quality and most interesting shot of the challenge.  I''m looking forward to finding out how you created the \"eye-ball\".  The lighting and perspective work especially well in this shot.  The darkened background makes the inside of the egg really pop - yet has a rich property, not just dim and dark.  Well done. 9</td>', 'Highest quality and most interesting shot of the challenge.  I''m looking forward to finding out how you created the \"eye-ball\".  The lighting and perspective work especially well in this shot.  The darkened background makes the inside of the egg really pop - yet has a rich property, not just dim and dark.  Well done. 9', '2003-11-26 02:50:53.000000', NULL, 1),
(495064, 48324, 7151, '<td valign="top">Bet I know who this is.... :-)  (Was just looking at your profile after your comment on my shot - at least I think so....)  Very nice work.  Don''t know if this was candid or staged, but the feeling is very natural, so either way doesn''t matter - it worked.  This is the best of the \"reaction\" shots - one of only a couple that don''t look like play-acting.  The soft tones and focus also help with the intimacy of the moment.  The only thing I don''t like is that I think the flares from the earrings were a little overdone. 8</td>', 'Bet I know who this is.... :-)  (Was just looking at your profile after your comment on my shot - at least I think so....)  Very nice work.  Don''t know if this was candid or staged, but the feeling is very natural, so either way doesn''t matter - it worked.  This is the best of the \"reaction\" shots - one of only a couple that don''t look like play-acting.  The soft tones and focus also help with the intimacy of the moment.  The only thing I don''t like is that I think the flares from the earrings were a little overdone. 8', '2003-11-26 02:51:03.000000', NULL, 1),
(495065, 48199, 7151, '<td valign="top">Nice job capturing the action.  Good surprise shot. 7</td>', 'Nice job capturing the action.  Good surprise shot. 7', '2003-11-26 02:51:10.000000', NULL, 1),
(495067, 48117, 7151, '<td valign="top">Cute idea.  Hope you don''t get penalized by the \"essence of surprise\" police - this is a great surprise, and well composed at that.  You pulled back enough to give it good context, but not so much as to diminish the prominance of the doorway.  The balance of tonallity between the room and the hall was also well done. 7</td>', 'Cute idea.  Hope you don''t get penalized by the \"essence of surprise\" police - this is a great surprise, and well composed at that.  You pulled back enough to give it good context, but not so much as to diminish the prominance of the doorway.  The balance of tonallity between the room and the hall was also well done. 7', '2003-11-26 02:51:19.000000', NULL, 1),
(495072, 47816, 7151, '<td valign="top">I don''t really understand how this relates to the challenge.  The photo itself is a little poignant, maybe more so with some context, but it seems mostly a snapshot.</td>', 'I don''t really understand how this relates to the challenge.  The photo itself is a little poignant, maybe more so with some context, but it seems mostly a snapshot.', '2003-11-26 02:55:15.000000', NULL, 1),
(495093, 48215, 7151, '<td valign="top">My first thought was that it was the dog''s birthday, and he was surprised.  Which didn''t work for me.  Now, I''m thinking maybe he''s the birthday surprise for somebody?  Even at that, it''s not a terribly engaging shot.  Nothing very cute, no eye contact with the pup, no context (beside the ribbon) to tell me how the surprise worked.  The black background seems to leave the dog issolated - almost gives it a sense of melancholy that contradicts the title.  Technically speaking, its an OK shot, no obvious flaws, though maybe the face is just a tad hot against the black background.</td>', 'My first thought was that it was the dog''s birthday, and he was surprised.  Which didn''t work for me.  Now, I''m thinking maybe he''s the birthday surprise for somebody?  Even at that, it''s not a terribly engaging shot.  Nothing very cute, no eye contact with the pup, no context (beside the ribbon) to tell me how the surprise worked.  The black background seems to leave the dog issolated - almost gives it a sense of melancholy that contradicts the title.  Technically speaking, its an OK shot, no obvious flaws, though maybe the face is just a tad hot against the black background.', '2003-11-26 03:06:16.000000', NULL, 1),
(495105, 48283, 7151, '<td valign="top">Not sure how this relates to surprise.  Is it that the birds are flying because they were surprised?  If so, what surprised them?  Seeing that would complete the scene.  As it is, it''s just some flying birds.  I personally don''t much like the noisy quality, especially in the bottom portion of the shot.  The color of the sky is nice.  The hectic action of the birds might be effective for certain purposes, but I don''t find it too appealing of itself.</td>', 'Not sure how this relates to surprise.  Is it that the birds are flying because they were surprised?  If so, what surprised them?  Seeing that would complete the scene.  As it is, it''s just some flying birds.  I personally don''t much like the noisy quality, especially in the bottom portion of the shot.  The color of the sky is nice.  The hectic action of the birds might be effective for certain purposes, but I don''t find it too appealing of itself.', '2003-11-26 03:09:34.000000', NULL, 1),
(495109, 48313, 7151, '<td valign="top">Looks like a zombie about to attack a car.  ;-)  Sorry, I just don''t see any "surprise" here - the person isn''t reacting, there''s no sense of movement in the car - nothing that gives me a sense of surprise.</td>', 'Looks like a zombie about to attack a car.  ;-)  Sorry, I just don''t see any "surprise" here - the person isn''t reacting, there''s no sense of movement in the car - nothing that gives me a sense of surprise.', '2003-11-26 03:12:10.000000', NULL, 1),
(495248, 48161, 10275, '<td valign="top">Great spontanious shot. I love the boys'' expressions in their faces. The movement of the birds livens it all up. I think it''s great that this is in b&amp;w as it takes the viewer to the boys and not to the background that would be too much if it were in colour. Well done.</td>', 'Great spontanious shot. I love the boys'' expressions in their faces. The movement of the birds livens it all up. I think it''s great that this is in b&w as it takes the viewer to the boys and not to the background that would be too much if it were in colour. Well done.', '2003-11-26 07:14:03.000000', NULL, 1),
(495251, 48265, 10275, '<td valign="top">Very well executed. The lighting is superb, the simple colours and background make this into very good photo. My only suggestion (and I know this was probably hard) would be to make the hamster face towards the viewer as he is saying Whats Up?...  10</td>', 'Very well executed. The lighting is superb, the simple colours and background make this into very good photo. My only suggestion (and I know this was probably hard) would be to make the hamster face towards the viewer as he is saying Whats Up?...  10', '2003-11-26 07:14:46.000000', NULL, 1),
(495253, 48307, 10275, '<td valign="top">Oh, I can definitely relate to this. Great lighting, so bright. Good focus, just a bit more space around the whole thing would have been better. Still great image. 10</td>', 'Oh, I can definitely relate to this. Great lighting, so bright. Good focus, just a bit more space around the whole thing would have been better. Still great image. 10', '2003-11-26 07:15:06.000000', NULL, 1),
(495257, 47747, 10275, '<td valign="top">Who surprised who in this shot? :-)) Great wildlife photo. Good composition. Love it in b&amp;w, as it brings up the textures. The background would have been better if it were more blurred (less dof), but since this is in b&amp;w it doesn''t really distract that much. 10</td>', 'Who surprised who in this shot? :-)) Great wildlife photo. Good composition. Love it in b&w, as it brings up the textures. The background would have been better if it were more blurred (less dof), but since this is in b&w it doesn''t really distract that much. 10', '2003-11-26 07:17:38.000000', NULL, 1),
(495259, 48250, 10275, '<td valign="top">Lovely spontanious shot - great frozen moment. The centre composition is not bad in this image, because you managed to frame it so the boy''s head is between the two windows. Few of my suggestions would include fixing the greenish cast on his skin and maybe using a polarizing filter to avoid distracting window reflections. Otherwise well done.</td>', 'Lovely spontanious shot - great frozen moment. The centre composition is not bad in this image, because you managed to frame it so the boy''s head is between the two windows. Few of my suggestions would include fixing the greenish cast on his skin and maybe using a polarizing filter to avoid distracting window reflections. Otherwise well done.', '2003-11-26 07:20:07.000000', NULL, 1),
(495260, 48177, 10275, '<td valign="top">This is just precious. The dof is excellent, the focus dead on. My suggestion would be for the composition - maybe crop it so the squarrel''s head would appear lower and more to the right with more image data included on the top and left (hope this makes sense). Very well done indeed.</td>', 'This is just precious. The dof is excellent, the focus dead on. My suggestion would be for the composition - maybe crop it so the squarrel''s head would appear lower and more to the right with more image data included on the top and left (hope this makes sense). Very well done indeed.', '2003-11-26 07:22:04.000000', NULL, 1),
(495266, 48199, 10275, '<td valign="top">Great action freeze. Well composed. Love the simple background. However a touch of colour somwhere in this image could make it even more fun. Maybe a different colour t-shirt. Still great shot. 10</td>', 'Great action freeze. Well composed. Love the simple background. However a touch of colour somwhere in this image could make it even more fun. Maybe a different colour t-shirt. Still great shot. 10', '2003-11-26 07:26:24.000000', NULL, 1),
(495267, 48144, 10275, '<td valign="top">Lovely head shot. So clean and sharp. My only suggesion would be to exclude the blue thing in the background and adjust the colours slightly to fix the greenish cast on her hair. Funny, she looks like she is ready to crack up :-))</td>', 'Lovely head shot. So clean and sharp. My only suggesion would be to exclude the blue thing in the background and adjust the colours slightly to fix the greenish cast on her hair. Funny, she looks like she is ready to crack up :-))', '2003-11-26 07:28:26.000000', NULL, 1),
(495268, 48278, 10275, '<td valign="top">This would have been superb surprise shot it the background wasn''t blurred. The man is falling and the blurr on him suggests that, but the background needs to be still for this to be effective. Also it might have looked better vertically cropped, as it would add to the feeling of height.</td>', 'This would have been superb surprise shot it the background wasn''t blurred. The man is falling and the blurr on him suggests that, but the background needs to be still for this to be effective. Also it might have looked better vertically cropped, as it would add to the feeling of height.', '2003-11-26 07:32:12.000000', NULL, 1),
(495270, 48304, 10275, '<td valign="top">I am sorry, but without your long title this would not really portray feeling of surprise. I can see it is taken on a cloudy day since your sky appears dull grey. You could boost the colours a little - mainly the red and yellow shades in the rocks and dry leaves to liven it up. It could be slightly sharper as well.</td>', 'I am sorry, but without your long title this would not really portray feeling of surprise. I can see it is taken on a cloudy day since your sky appears dull grey. You could boost the colours a little - mainly the red and yellow shades in the rocks and dry leaves to liven it up. It could be slightly sharper as well.', '2003-11-26 07:35:05.000000', NULL, 1),
(495272, 48284, 10275, '<td valign="top">Ooops, this would be a good one :-)) This is well lit, the colours are fine, but it seems a bit oversharpened in few spots that pixelates it (her hair and glasses). The triangle composition works well.</td>', 'Ooops, this would be a good one :-)) This is well lit, the colours are fine, but it seems a bit oversharpened in few spots that pixelates it (her hair and glasses). The triangle composition works well.', '2003-11-26 07:37:03.000000', NULL, 1),
(495274, 48220, 10275, '<td valign="top">Beautiful. Love the way you lit this. The background is perfect, but the little glare on the left could have been avoided. Also if you are really centering this, then you could crop a bit more on the right to make it equal on both sides.</td>', 'Beautiful. Love the way you lit this. The background is perfect, but the little glare on the left could have been avoided. Also if you are really centering this, then you could crop a bit more on the right to make it equal on both sides.', '2003-11-26 07:38:45.000000', NULL, 1),
(495275, 48283, 10275, '<td valign="top">The colours are very nice. The water looks a bit pixelated. The birds are just beautiful, especially in the top portion of the image. I just can''t seem to find the point of surprise in this photo.</td>', 'The colours are very nice. The water looks a bit pixelated. The birds are just beautiful, especially in the top portion of the image. I just can''t seem to find the point of surprise in this photo.', '2003-11-26 07:40:09.000000', NULL, 1),
(495277, 48126, 8637, '<td valign="top">Great shot...anxious to see how you did this one.</td>', 'Great shot...anxious to see how you did this one.', '2003-11-26 07:41:59.000000', NULL, 1),
(495278, 48324, 10275, '<td valign="top">Lovely image. Great in b&amp;w. The reflection stars on her earings add nice touch to the whole photo. I don''t like the glare on her teeth and gums though as it attracts too much attention. The man''s hand appears tiny bit out of focus, but the image holds so it''s not distracting. The top left corner glow could have been cropped out as well. Otherwise good.</td>', 'Lovely image. Great in b&w. The reflection stars on her earings add nice touch to the whole photo. I don''t like the glare on her teeth and gums though as it attracts too much attention. The man''s hand appears tiny bit out of focus, but the image holds so it''s not distracting. The top left corner glow could have been cropped out as well. Otherwise good.', '2003-11-26 07:43:18.000000', NULL, 1),
